import { useId, useState } from 'react';
import { t } from '@/i18n/index.js';
import { useAuth } from '@/features/auth/session.js';
import { CANCEL_REASONS, markAsked, sendCancelReason, wasAsked } from './cancelAsk.js';
import styles from './CancelReason.module.css';

/**
 * The one optional question after a paid plan was cancelled. Shown in
 * Settings → Plan while the cancelled plan still runs; one tap answers it,
 * Skip dismisses it, and either way it never comes back on this device.
 */
export function CancelReason(): React.JSX.Element | null {
  const accountId = useAuth((s) => s.user?.id);
  const [state, setState] = useState<'ask' | 'thanks' | 'gone'>(() =>
    accountId === undefined || wasAsked(accountId) ? 'gone' : 'ask',
  );
  const questionId = useId();
  if (accountId === undefined || state === 'gone') return null;
  if (state === 'thanks') {
    return (
      <p className={styles.thanks} role="status">
        {t('cancelReason.thanks')}
      </p>
    );
  }
  return (
    <div className={styles.card}>
      <p className={styles.question} id={questionId}>
        {t('cancelReason.question')}
      </p>
      <p className={styles.hint}>{t('cancelReason.hint')}</p>
      <div className={styles.reasons} role="group" aria-labelledby={questionId}>
        {CANCEL_REASONS.map((reason) => (
          <button
            key={reason}
            type="button"
            className={styles.reason}
            onClick={() => {
              markAsked(accountId);
              sendCancelReason(reason);
              setState('thanks');
            }}
          >
            {t(`cancelReason.${reason}`)}
          </button>
        ))}
      </div>
      <button
        type="button"
        className={styles.skip}
        onClick={() => {
          markAsked(accountId);
          setState('gone');
        }}
      >
        {t('cancelReason.skip')}
      </button>
    </div>
  );
}
