import { Link } from 'react-router-dom';
import { t } from '@/i18n/index.js';
import { settingsPath } from '@/features/settings/paths.js';
import { pitchDays, useInviteReward } from './useInviteReward.js';
import styles from './InviteLine.module.css';

/**
 * One quiet line under the plans (growth study 2026-10-13, "Plan /
 * Upgrade screen"; "Pay or invite", sales plan 6-و): another way to Pro
 * days, never a button that competes with buying. Said only with the days
 * the server gives (absent while the programme is off), never to somebody
 * who pays (they are thanked, not given days), and wherever invitations are
 * offered (`where.ts`: the web, the desktop and the Android app; never the
 * iPhone app).
 */
export function InviteLine({ onOpen }: { onOpen?: () => void }): React.JSX.Element | null {
  const reward = useInviteReward();
  if (reward === undefined) return null;
  return (
    <p className={styles.line}>
      {reward.friends === undefined
        ? t('invite.planLine', { days: reward.days })
        : t('invite.pitchLine', { count: reward.friends, days: pitchDays(reward) })}{' '}
      <Link to={`${settingsPath('invite')}?via=plan`} className={styles.link} onClick={onOpen}>
        {t('invite.cardAction')}
      </Link>
    </p>
  );
}
