/**
 * "Why did you cancel?" (the data plan, owner 22 Oct 2026): one optional
 * question, asked once on this device for an account whose paid plan has
 * been cancelled and still runs to its end. One tap, no note. The server
 * keeps it only for a cancelled paid plan and only the first answer, so a
 * second device asking again changes nothing.
 *
 * Which accounts were asked lives in the small preferences store (account
 * ids, not answers), so Skip is remembered and the card never comes back.
 */
import { billing as billingApi } from '@/api/endpoints.js';
import type { ApiCancelReason } from '@/api/types.js';
import { platform } from '@/lib/platform/index.js';

/** The reasons, in the order the card shows them (the contract's CancelReason). */
export const CANCEL_REASONS: readonly ApiCancelReason[] = [
  'too_expensive',
  'not_using',
  'missing_feature',
  'ai_not_good',
  'other_app',
  'temporary',
  'other',
];

const KEY = 'wb.cancelAsked';

function asked(): string[] {
  try {
    return (platform.prefs.get(KEY) ?? '').split(',').filter((id) => id !== '');
  } catch {
    return [];
  }
}

/** Whether this account was already asked on this device. */
export function wasAsked(accountId: string): boolean {
  return asked().includes(accountId);
}

/** Remembers the account was asked, answered or skipped. */
export function markAsked(accountId: string): void {
  try {
    platform.prefs.set(KEY, [...asked().filter((id) => id !== accountId), accountId].slice(-20).join(','));
  } catch {
    // Asking again on a device that cannot remember is the lesser harm.
  }
}

/** Sends the answer, fire and forget. */
export function sendCancelReason(reason: ApiCancelReason): void {
  try {
    void billingApi.cancelReason(reason).catch(() => undefined);
  } catch {
    // Nothing a learner should hear about.
  }
}
