/**
 * What Pro gives, in the server's numbers where it sent them (`GET /config`
 * `limits`, public since 21 Oct 2026) and in plain words where it did not.
 * Nothing here writes a number down: every one comes from `limits`.
 */
import { t } from '@/i18n/index.js';
import type { PlanLimits } from '@/lib/useConfig.js';

/** The sheet's lead for the AI moments and the plan row: the numbers, or the words without them. */
export function cardsLead(limits: PlanLimits, fallback: string): string {
  const pro = limits.pro?.aiCardsDaily;
  const free = limits.free?.aiCardsDaily;
  if (pro !== undefined && free !== undefined) return t('pro.cardsInstead', { pro, free });
  if (pro !== undefined) return t('ai.proLine', { count: pro });
  return fallback;
}

/** The perk line for AI cards. */
export function cardsPerk(limits: PlanLimits): string {
  const pro = limits.pro?.aiCardsDaily;
  return pro === undefined ? t('chip.cards') : t('chip.cardsN', { count: pro });
}

/** The plan row's note: what Pro is and the lowest price. */
export function rowNote(limits: PlanLimits, amount: string): string {
  const pro = limits.pro?.aiCardsDaily;
  return pro === undefined ? t('upgrade.rowNote', { amount }) : t('upgrade.rowNoteN', { count: pro, amount });
}
